#include <string>
using namespace std;

class Solution {
public:
    bool canBeValid(string s, string locked) {
        if (s.size() % 2) return false;

        int lo = 0, hi = 0;
        for (int i = 0; i < s.size(); ++i) {
            if (locked[i] == '0') {
                lo--;
                hi++;
            } else {
                if (s[i] == '(') {
                    lo++;
                    hi++;
                } else {
                    lo--;
                    hi--;
                }
            }
            if (hi < 0) return false;
            lo = max(lo, 0);
        }

        return lo == 0;
    }
};
